std::unique_ptr<Session> make_session(const Config& config) {
  auto s = std::make_unique<Session>(config);
  s->open();
  return s;
}

void run(const Config& config) {
  auto s = make_session(config);
  s->pump();
  pool.hold(std::move(s));
}
